PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ssn-system: <http://example.org/ssn-system/>

SELECT ?property ?performanceEffect
WHERE {
  ?property rdfs:subClassOf* ssn:Property .
  ?property rdfs:subClassOf [ 
    a owl:Restriction ;
    owl:onProperty ssn-system:Frequency ;
    owl:someValuesFrom ?performanceEffect
  ].
}

PREFIX ssn: <http://www.w3.org/ns/ssn/>
