PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property ?impact
WHERE {
  ?property rdfs:subClassOf* ssn-system:SystemProperty .
  FILTER (?property = ssn-system:ResponseTime || ?property = ssn-system:Latency)
  OPTIONAL {
    ?property rdfs:comment ?impact
  }
}

