PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?relationship
WHERE {
  :isComposedBy rdf:type owl:ObjectProperty ;
                rdfs:domain :ComposedThing ;
                rdfs:range owl:Thing .
  :ComposedThing rdf:type owl:Class .
  BIND("isComposedBy is an ObjectProperty that has ComposedThing as its domain and Thing as its range." AS ?relationship)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
