  <http://iot.linkeddata.es/def/core#> dc:publisher ?publisher
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX core: <http://iot.linkeddata.es/def/core#>
PREFIX wot: <http://iot.linkeddata.es/def/wot#>

SELECT ?creator ?contributor
WHERE {
  {
    core: dcterms:creator ?creator .
  }
  UNION
  {
    core: dcterms:contributor ?contributor .
  }
  FILTER(?creator = ?contributor)
  {
    wot: dcterms:creator|dcterms:contributor ?commonPerson .
    FILTER(?commonPerson = ?creator || ?commonPerson = ?contributor)
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
