SELECT ?person ?role
WHERE {
  {
    <http://iot.linkeddata.es/def/core#> dcterms:creator ?person.
  }
  UNION
  {
    <http://iot.linkeddata.es/def/core#> dcterms:contributor ?person.
  }
  OPTIONAL {
    ?person foaf:role ?role.
  }
}

