PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX vs: <http://www.w3.org/2003/06/sw-vocab-status/ns#>

SELECT (COUNT(DISTINCT ?creator) AS ?numberOfCreators)
WHERE {
  ?resource dc:creator ?creator ;
            vs:term_status ?termStatus .
}

SELECT ?organization
WHERE {
  ?organization a org:Organization ;
                :hasPartnershipWith ?partner .
}
GROUP BY ?organization
HAVING (COUNT(?partner) > 3)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX org: <http://www.w3.org/ns/org#>
PREFIX ex: <http://example.org/>

SELECT (COUNT(DISTINCT ?org) AS ?count)
WHERE {
  ?org a org:Organization ;
       ex:hasPartnershipWith ?partner ;
       ex:locatedIn ?city .
  ?partner a org:Organization ;
           ex:locatedIn ?city .
  FILTER(?org != ?partner)
}
